          | :figure
          | :form
          | :generic
          | :grid
          | :gridcell
          | :group
          | :heading
          | :img
          | :insertion
          | :link
          | :list
          | :listbox
          | :listitem
          | :log
          | :main
          | :marquee
          | :math
          | :meter
          | :menu
          | :menubar
          | :menuitem
          | :menuitemcheckbox
          | :menuitemradio
          | :navigation
          | :none
          | :note
          | :option
          | :paragraph
          | :presentation
          | :progressbar
          | :radio
          | :radiogroup
          | :region
          | :row
          | :rowgroup
          | :rowheader
          | :scrollbar
          | :search
