    for (const currentURL of ['https://google.com', 'https://bbc.com']) {
      await page.goto(currentURL);
      const element = await page.mainFrame().waitForSelector('img');
      console.log('Loaded image: ' + await element.getAttribute('src'));
    }
    await browser.close();
  })();
